"""A recoverable, idempotent single-writer JSON-file inbox.

The persistent document is ``{"version": 1, "records": [...]}`` where every
record is ``{"id": str, "payload": <json value>, "status": str}`` and records
keep their original submission order.

Durability model: every mutating method serialises the *next* document into a
temporary file that lives in the destination directory, flushes and fsyncs it,
and only then atomically installs it with ``os.replace``.  In-memory state is
swapped only after the replace succeeded, so a failing save leaves both the
previous file and :meth:`Inbox.snapshot` exactly as they were.
"""

from __future__ import annotations

import copy
import json
import math
import os
import tempfile

__all__ = ["Inbox"]

STATES = ("pending", "running", "completed", "interrupted")
MAX_ID_LENGTH = 64
_VERSION = 1
_MAX_DEPTH = 200


class _InvalidInput(ValueError, TypeError):
    """Rejection of an unsupported *type* of argument.

    The contract pins ``ValueError`` for rejected values, while a wrongly typed
    argument is idiomatically a ``TypeError``; raising a class that is both
    keeps every reasonable ``except`` clause working.
    """


def _canonical(payload):
    """Canonical JSON text used for payload equality (key order irrelevant)."""
    return json.dumps(
        payload,
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    )


def _normalize_payload(value, _depth=0, _active=None):
    """Validate ``value`` as a JSON value and return a detached plain copy.

    Raises ValueError for anything that is not part of the accepted JSON value
    domain (non-string object keys, non-finite numbers, bytes/tuple/set/...,
    reference cycles).
    """
    if value is None or value is True or value is False:
        return value
    if _depth > _MAX_DEPTH:
        raise ValueError("payload is too deeply nested or contains a cycle")
    if _active is None:
        _active = set()
    if isinstance(value, str):
        return str(value)
    if isinstance(value, int):
        return int(value)
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("payload numbers must be finite")
        return float(value)
    if isinstance(value, list):
        marker = id(value)
        if marker in _active:
            raise ValueError("payload must not contain reference cycles")
        _active.add(marker)
        try:
            return [
                _normalize_payload(item, _depth + 1, _active) for item in value
            ]
        finally:
            _active.discard(marker)
    if isinstance(value, dict):
        marker = id(value)
        if marker in _active:
            raise ValueError("payload must not contain reference cycles")
        _active.add(marker)
        try:
            normalized = {}
            for key, item in value.items():
                if not isinstance(key, str):
                    raise ValueError("payload object keys must be strings")
                normalized[str(key)] = _normalize_payload(
                    item, _depth + 1, _active
                )
            return normalized
        finally:
            _active.discard(marker)
    raise _InvalidInput(
        "unsupported payload type: %s" % type(value).__name__
    )


def _validate_identifier(identifier):
    if not isinstance(identifier, str):
        raise _InvalidInput(
            "id must be a nonempty string of at most 64 characters"
        )
    if not identifier or len(identifier) > MAX_ID_LENGTH:
        raise ValueError("id must be a nonempty string of at most 64 characters")
    return identifier


def _copy_record(record):
    return {
        "id": record["id"],
        "payload": copy.deepcopy(record["payload"]),
        "status": record["status"],
    }


class Inbox:
    """A durable inbox persisted as a single JSON document."""

    def __init__(self, path):
        self.path = path
        self._records = []
        self._load()

    # ------------------------------------------------------------------
    # public API
    # ------------------------------------------------------------------
    def submit(self, identifier, payload):
        """Add a record, or return the existing identical record."""
        _validate_identifier(identifier)
        normalized = _normalize_payload(payload)
        for record in self._records:
            if record["id"] != identifier:
                continue
            if _canonical(record["payload"]) != _canonical(normalized):
                raise ValueError(
                    "conflicting payload for existing id %r" % (identifier,)
                )
            return _copy_record(record)
        updated = [dict(record) for record in self._records]
        new_record = {"id": identifier, "payload": normalized, "status": "pending"}
        updated.append(new_record)
        self._save(updated)
        self._records = updated
        return _copy_record(new_record)

    def start_next(self):
        """Persist the first pending record as running and return a copy."""
        for record in self._records:
            if record["status"] == "running":
                raise RuntimeError("an inbox record is already running")
        index = None
        for position, record in enumerate(self._records):
            if record["status"] == "pending":
                index = position
                break
        if index is None:
            return None
        updated = [dict(record) for record in self._records]
        updated[index]["status"] = "running"
        self._save(updated)
        self._records = updated
        return _copy_record(updated[index])

    def finish(self, identifier):
        """Mark a running record completed and return a copy of it."""
        for record in self._records:
            if record["id"] != identifier:
                continue
            if record["status"] == "completed":
                return _copy_record(record)
            if record["status"] != "running":
                raise ValueError(
                    "record %r is %s, not running"
                    % (identifier, record["status"])
                )
            index = self._records.index(record)
            updated = [dict(item) for item in self._records]
            updated[index]["status"] = "completed"
            self._save(updated)
            self._records = updated
            return _copy_record(updated[index])
        raise KeyError(identifier)

    def snapshot(self):
        """Return a detached deep copy of the stored records."""
        return [_copy_record(record) for record in self._records]

    # ------------------------------------------------------------------
    # persistence
    # ------------------------------------------------------------------
    def _load(self):
        try:
            with open(self.path, "r", encoding="utf-8-sig") as handle:
                raw = handle.read()
        except FileNotFoundError:
            self._records = []
            return
        try:
            document = json.loads(raw)
        except ValueError as exc:
            raise ValueError("invalid inbox file: %s" % (exc,)) from exc
        records = self._validate_document(document)
        if any(record["status"] == "running" for record in records):
            recovered = [dict(record) for record in records]
            for record in recovered:
                if record["status"] == "running":
                    record["status"] = "interrupted"
            self._save(recovered)
            records = recovered
        self._records = records

    @staticmethod
    def _validate_document(document):
        if not isinstance(document, dict):
            raise ValueError("inbox document must be an object")
        if set(document) != {"version", "records"}:
            raise ValueError("inbox document must have version and records")
        version = document["version"]
        if isinstance(version, bool) or not isinstance(version, int):
            raise ValueError("inbox document version must be 1")
        if version != _VERSION:
            raise ValueError("unsupported inbox document version: %r" % (version,))
        records = document["records"]
        if not isinstance(records, list):
            raise ValueError("inbox document records must be a list")
        validated = []
        seen = set()
        for entry in records:
            if not isinstance(entry, dict) or set(entry) != {
                "id",
                "payload",
                "status",
            }:
                raise ValueError("invalid record schema")
            identifier = entry["id"]
            _validate_identifier(identifier)
            if identifier in seen:
                raise ValueError("duplicate stored id: %r" % (identifier,))
            seen.add(identifier)
            status = entry["status"]
            if not isinstance(status, str) or status not in STATES:
                raise ValueError("invalid record status: %r" % (status,))
            payload = _normalize_payload(entry["payload"])
            validated.append(
                {"id": identifier, "payload": payload, "status": status}
            )
        return validated

    def _save(self, records):
        """Durably write ``records`` as the whole document, or raise OSError."""
        destination = os.fspath(self.path)
        directory = os.path.dirname(os.path.abspath(destination))
        os.makedirs(directory, exist_ok=True)
        document = {"version": _VERSION, "records": records}
        data = json.dumps(document, ensure_ascii=False, allow_nan=False)
        temporary = None
        try:
            descriptor, temporary = tempfile.mkstemp(
                prefix=".inbox-", suffix=".tmp", dir=directory
            )
            try:
                handle = os.fdopen(descriptor, "w", encoding="utf-8", newline="\n")
            except BaseException:
                os.close(descriptor)
                raise
            with handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, destination)
            temporary = None
        finally:
            if temporary is not None:
                try:
                    os.unlink(temporary)
                except OSError:
                    pass

