"""A single-process, single-writer, recoverable idempotent JSON-file inbox."""

import copy
import json
import math
import os
import tempfile

_VERSION = 1
_STATUSES = ("pending", "running", "completed", "interrupted")
_FIELDS = ("id", "payload", "status")
_MAX_ID_LENGTH = 64
_JSON_ARGS = dict(
    sort_keys=True,
    ensure_ascii=False,
    separators=(",", ":"),
    allow_nan=False,
)


def _validate_id(identifier):
    if not isinstance(identifier, str):
        raise ValueError("id must be a string")
    if not identifier:
        raise ValueError("id must be nonempty")
    if len(identifier) > _MAX_ID_LENGTH:
        raise ValueError("id must be at most 64 characters")


def _validate_payload(payload):
    if payload is None:
        return
    if isinstance(payload, bool):
        return
    if isinstance(payload, int):
        return
    if isinstance(payload, float):
        if not math.isfinite(payload):
            raise ValueError("payload contains a nonfinite number")
        return
    if isinstance(payload, str):
        return
    if isinstance(payload, list):
        for item in payload:
            _validate_payload(item)
        return
    if isinstance(payload, dict):
        for key, value in payload.items():
            if not isinstance(key, str):
                raise ValueError("payload object keys must be strings")
            _validate_payload(value)
        return
    raise ValueError("payload is not a JSON value")


def _canonical(payload):
    return json.dumps(payload, **_JSON_ARGS)


def _validate_record(raw):
    if not isinstance(raw, dict):
        raise ValueError("record must be an object")
    if set(raw.keys()) != set(_FIELDS):
        raise ValueError("record must have exactly id, payload, status")
    identifier = raw["id"]
    _validate_id(identifier)
    status = raw["status"]
    if not isinstance(status, str) or status not in _STATUSES:
        raise ValueError("record has an invalid status")
    payload = raw["payload"]
    _validate_payload(payload)
    return {"id": identifier, "payload": copy.deepcopy(payload), "status": status}


class Inbox:
    def __init__(self, path):
        self.path = path
        self._records = []
        self._load()

    # -- persistence -----------------------------------------------------
    def _load(self):
        filename = os.fspath(self.path)
        try:
            with open(filename, "r", encoding="utf-8") as handle:
                text = handle.read()
        except FileNotFoundError:
            return
        try:
            document = json.loads(text)
        except ValueError as exc:
            raise ValueError("malformed inbox file") from exc

        if not isinstance(document, dict):
            raise ValueError("document must be an object")
        if set(document.keys()) != {"version", "records"}:
            raise ValueError("document must have exactly version and records")
        version = document["version"]
        if type(version) is not int or version != _VERSION:
            raise ValueError("unsupported document version")
        raw_records = document["records"]
        if not isinstance(raw_records, list):
            raise ValueError("records must be a list")

        records = []
        seen = set()
        for raw in raw_records:
            record = _validate_record(raw)
            if record["id"] in seen:
                raise ValueError("duplicate record id")
            seen.add(record["id"])
            records.append(record)

        recovered = False
        for record in records:
            if record["status"] == "running":
                record["status"] = "interrupted"
                recovered = True
        if recovered:
            self._save(records)
        self._records = records

    def _save(self, records):
        filename = os.fspath(self.path)
        directory = os.path.dirname(os.path.abspath(filename))
        os.makedirs(directory, exist_ok=True)
        document = {"version": _VERSION, "records": records}
        data = json.dumps(document, **_JSON_ARGS).encode("utf-8")

        handle_fd, tmp_path = tempfile.mkstemp(
            dir=directory,
            prefix=os.path.basename(filename) + ".",
            suffix=".tmp",
        )
        try:
            with os.fdopen(handle_fd, "wb") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp_path, filename)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    # -- public API ------------------------------------------------------
    def submit(self, identifier, payload):
        _validate_id(identifier)
        _validate_payload(payload)
        canonical = _canonical(payload)

        for record in self._records:
            if record["id"] == identifier:
                if _canonical(record["payload"]) == canonical:
                    return copy.deepcopy(record)
                raise ValueError("conflicting duplicate id")

        new_record = {
            "id": identifier,
            "payload": copy.deepcopy(payload),
            "status": "pending",
        }
        records = list(self._records)
        records.append(new_record)
        self._save(records)
        self._records = records
        return copy.deepcopy(new_record)

    def start_next(self):
        for record in self._records:
            if record["status"] == "running":
                raise RuntimeError("a record is already running")

        for index, record in enumerate(self._records):
            if record["status"] == "pending":
                records = list(self._records)
                updated = dict(record)
                updated["status"] = "running"
                records[index] = updated
                self._save(records)
                self._records = records
                return copy.deepcopy(updated)
        return None

    def finish(self, identifier):
        for index, record in enumerate(self._records):
            if record["id"] == identifier:
                if record["status"] == "completed":
                    return copy.deepcopy(record)
                if record["status"] != "running":
                    raise ValueError("record is not running")
                records = list(self._records)
                updated = dict(record)
                updated["status"] = "completed"
                records[index] = updated
                self._save(records)
                self._records = records
                return copy.deepcopy(updated)
        raise KeyError(identifier)

    def snapshot(self):
        return [copy.deepcopy(record) for record in self._records]

class Inbox:
    def __init__(self, path):
        self.path = path
        raise NotImplementedError("Implement durable inbox")

    def submit(self, identifier, payload):
        raise NotImplementedError

    def start_next(self):
        raise NotImplementedError

    def finish(self, identifier):
        raise NotImplementedError

    def snapshot(self):
        raise NotImplementedError

"""Durable, recoverable, idempotent JSON-file inbox (standard library only)."""

import copy
import json
import math
import os
import tempfile

__all__ = ["Inbox"]

_PENDING = "pending"
_RUNNING = "running"
_COMPLETED = "completed"
_INTERRUPTED = "interrupted"
_STATES = frozenset({_PENDING, _RUNNING, _COMPLETED, _INTERRUPTED})
_MAX_ID_LENGTH = 64
_VERSION = 1


def _is_valid_payload(value, _seen=None):
    """True iff value is a JSON value built only from builtin types."""
    if _seen is None:
        _seen = set()
    if value is None:
        return True
    value_type = type(value)
    if value_type is bool or value_type is int:
        return True
    if value_type is float:
        return math.isfinite(value)
    if value_type is str:
        return True
    if value_type is list:
        cid = id(value)
        if cid in _seen:
            return False
        _seen.add(cid)
        try:
            return all(_is_valid_payload(item, _seen) for item in value)
        finally:
            _seen.discard(cid)
    if value_type is dict:
        cid = id(value)
        if cid in _seen:
            return False
        _seen.add(cid)
        try:
            for key, item in value.items():
                if type(key) is not str:
                    return False
                if not _is_valid_payload(item, _seen):
                    return False
            return True
        finally:
            _seen.discard(cid)
    return False


def _canonical_payload(payload):
    return json.dumps(
        payload,
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    )


def _validate_identifier(identifier):
    if not isinstance(identifier, str) or not identifier or len(identifier) > _MAX_ID_LENGTH:
        raise ValueError(
            "identifier must be a nonempty string of at most "
            f"{_MAX_ID_LENGTH} characters"
        )


class Inbox:
    """Single-process, single-writer durable inbox."""

    def __init__(self, path):
        self.path = path
        self._path = os.fspath(path)
        self._records = []
        self._load()

    # -- persistence ----------------------------------------------------
    def _save(self, records):
        document = {"version": _VERSION, "records": records}
        text = json.dumps(
            document,
            ensure_ascii=False,
            separators=(",", ":"),
            allow_nan=False,
        )
        directory = os.path.dirname(os.path.abspath(self._path))
        os.makedirs(directory, exist_ok=True)
        fd = None
        tmp_path = None
        try:
            fd, tmp_path = tempfile.mkstemp(
                prefix=".inbox-", suffix=".tmp", dir=directory
            )
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                fd = None
                handle.write(text)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp_path, self._path)
            tmp_path = None
        finally:
            if fd is not None:
                os.close(fd)
            if tmp_path is not None:
                try:
                    os.remove(tmp_path)
                except OSError:
                    pass

    # -- loading / validation ------------------------------------------
    def _load(self):
        if not os.path.exists(self._path):
            self._records = []
            return
        with open(self._path, "r", encoding="utf-8") as handle:
            text = handle.read()
        try:
            document = json.loads(text)
        except ValueError as exc:
            raise ValueError(f"malformed inbox file: {exc}") from exc

        records = self._validate_document(document)

        recovered = False
        for record in records:
            if record["status"] == _RUNNING:
                record["status"] = _INTERRUPTED
                recovered = True
        if recovered:
            self._save(records)

        self._records = records

    def _validate_document(self, document):
        if type(document) is not dict:
            raise ValueError("inbox document must be a JSON object")
        if set(document.keys()) != {"version", "records"}:
            raise ValueError("inbox document must have exactly 'version' and 'records'")
        version = document["version"]
        if type(version) is not int or version != _VERSION:
            raise ValueError("unsupported inbox document version")
        raw_records = document["records"]
        if type(raw_records) is not list:
            raise ValueError("inbox 'records' must be a list")

        records = []
        seen_ids = set()
        for raw in raw_records:
            if type(raw) is not dict:
                raise ValueError("each record must be a JSON object")
            if set(raw.keys()) != {"id", "payload", "status"}:
                raise ValueError("each record must have exactly id, payload, status")
            identifier = raw["id"]
            _validate_identifier(identifier)
            if identifier in seen_ids:
                raise ValueError(f"duplicate stored id: {identifier!r}")
            seen_ids.add(identifier)
            status = raw["status"]
            if status not in _STATES:
                raise ValueError(f"invalid record status: {status!r}")
            payload = raw["payload"]
            if not _is_valid_payload(payload):
                raise ValueError("invalid record payload")
            records.append(
                {
                    "id": identifier,
                    "payload": copy.deepcopy(payload),
                    "status": status,
                }
            )
        return records

    # -- public API -----------------------------------------------------
    def submit(self, identifier, payload):
        _validate_identifier(identifier)
        if not _is_valid_payload(payload):
            raise ValueError("payload must be a JSON value")

        canonical = _canonical_payload(payload)
        for record in self._records:
            if record["id"] == identifier:
                if _canonical_payload(record["payload"]) == canonical:
                    return copy.deepcopy(record)
                raise ValueError(f"conflicting duplicate id: {identifier!r}")

        new_record = {
            "id": identifier,
            "payload": copy.deepcopy(payload),
            "status": _PENDING,
        }
        new_records = self._records + [new_record]
        self._save(new_records)
        self._records = new_records
        return copy.deepcopy(new_record)

    def start_next(self):
        for record in self._records:
            if record["status"] == _RUNNING:
                raise RuntimeError("a record is already running")

        index = None
        for position, record in enumerate(self._records):
            if record["status"] == _PENDING:
                index = position
                break
        if index is None:
            return None

        new_records = copy.deepcopy(self._records)
        new_records[index]["status"] = _RUNNING
        self._save(new_records)
        self._records = new_records
        return copy.deepcopy(new_records[index])

    def finish(self, identifier):
        for position, record in enumerate(self._records):
            if record["id"] != identifier:
                continue
            if record["status"] == _COMPLETED:
                return copy.deepcopy(record)
            if record["status"] != _RUNNING:
                raise ValueError(
                    f"cannot finish record in state {record['status']!r}"
                )
            new_records = copy.deepcopy(self._records)
            new_records[position]["status"] = _COMPLETED
            self._save(new_records)
            self._records = new_records
            return copy.deepcopy(new_records[position])
        raise KeyError(identifier)

    def snapshot(self):
        return copy.deepcopy(self._records)

