import re

_IDENTIFIER = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")


class Router:
    def __init__(self):
        self.routes = []

    def add(self, pattern, handler):
        if not isinstance(pattern, str) or not pattern.startswith("/"):
            raise ValueError(pattern)
        if "?" in pattern or "#" in pattern:
            raise ValueError(pattern)

        segments = self._split(pattern)
        seen = set()
        for segment in segments:
            if segment.startswith(":"):
                name = segment[1:]
                if not _IDENTIFIER.match(name):
                    raise ValueError(pattern)
                if name in seen:
                    raise ValueError(pattern)
                seen.add(name)

        normalized = "/" + "/".join(segments) if segments else "/"
        static = sum(1 for segment in segments if not segment.startswith(":"))

        for index, (existing, _segments, _handler, _static) in enumerate(self.routes):
            if existing == normalized:
                self.routes[index] = (normalized, segments, handler, static)
                return

        self.routes.append((normalized, segments, handler, static))

    def resolve(self, path):
        if not isinstance(path, str) or not path.startswith("/"):
            raise ValueError(path)

        original = path
        path = self._strip_tail(path)
        segments = self._split(path)

        best = None
        for _normalized, pattern, handler, static in self.routes:
            if len(pattern) != len(segments):
                continue
            params = {}
            matched = True
            for wanted, actual in zip(pattern, segments):
                if wanted.startswith(":"):
                    params[wanted[1:]] = actual
                elif wanted != actual:
                    matched = False
                    break
            if matched and (best is None or static > best[0]):
                best = (static, handler, params)

        if best is None:
            raise KeyError(original)
        return best[1], best[2]

    @staticmethod
    def _split(text):
        return [part for part in text.split("/") if part != ""]

    @staticmethod
    def _strip_tail(path):
        cut = len(path)
        for marker in ("?", "#"):
            index = path.find(marker)
            if index != -1 and index < cut:
                cut = index
        return path[:cut]

