"""Customer reporting, delegating all monetary math to :mod:`pricing`."""

from decimal import Decimal

import pricing

REPORT_FORMAT = 'customer-totals-v1'


def customer_totals(orders):
    """Aggregate already-rounded line amounts per customer, sorted by name.

    Each order has ``customer``, ``tier`` and ``items``.  An order with no
    items still contributes a ``0.00`` row for its customer.  Caller data is
    never mutated.
    """
    totals = {}
    for order in orders:
        customer = order['customer']
        tier = order.get('tier', 'bronze')
        # Validate the tier even when the order has no line items.
        pricing.validate_tier(tier)

        if customer not in totals:
            totals[customer] = Decimal('0')
        for item in order['items']:
            amount = pricing.price_line(item['unit_price'], item['quantity'], tier)
            totals[customer] += amount

    return [
        {'customer': customer, 'total': f'{totals[customer]:.2f}'}
        for customer in sorted(totals)
    ]

