class PriceLineTest(unittest.TestCase):
    def test_round_half_up_once(self):
        # 2.345 * 10 * 0.90 * 0.95 = 20.04975 -> 20.05
        self.assertEqual(pricing.price_line('2.345', 10, 'silver'), Decimal('20.05'))
        # 1.005 * 1 -> 1.01 (half up, not half even)
        self.assertEqual(pricing.price_line('1.005', 1), Decimal('1.01'))
        self.assertEqual(pricing.price_line('1.015', 1), Decimal('1.02'))
        # Rounds only once: 0.005 * 0.90 = 0.0045 -> 0.00
        self.assertEqual(pricing.price_line('0.005', 1, 'silver'), Decimal('0.00'))

    def test_tiers_and_bulk(self):
        self.assertEqual(pricing.price_line('10', 1, 'bronze'), Decimal('10.00'))
        self.assertEqual(pricing.price_line('10', 1, 'silver'), Decimal('9.00'))
        self.assertEqual(pricing.price_line('10', 1, 'gold'), Decimal('8.00'))
        # bulk only at >= 10
        self.assertEqual(pricing.price_line('10', 9), Decimal('90.00'))
        self.assertEqual(pricing.price_line('10', 10), Decimal('95.00'))

    def test_returns_decimal(self):
        self.assertIsInstance(pricing.price_line('1', 1), Decimal)

