"""Recoverable, idempotent single-process JSON-file inbox."""

import copy
import json
import math
import os
import tempfile

_STATUSES = frozenset({"pending", "running", "completed", "interrupted"})
_MAX_ID = 64
_VERSION = 1


def _validate_id(identifier):
    if not isinstance(identifier, str):
        raise ValueError("id must be a string")
    if not identifier:
        raise ValueError("id must be nonempty")
    if len(identifier) > _MAX_ID:
        raise ValueError("id must be at most %d characters" % _MAX_ID)


def _validate_payload(value):
    if value is None or isinstance(value, bool):
        return
    if isinstance(value, str):
        return
    if isinstance(value, int):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("non-finite number in payload")
        return
    if isinstance(value, list):
        for item in value:
            _validate_payload(item)
        return
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise ValueError("payload object keys must be strings")
            _validate_payload(item)
        return
    raise ValueError("unsupported payload type: %r" % (type(value).__name__,))


def _canonical(payload):
    return json.dumps(
        payload,
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    )


def _validate_record(record):
    if not isinstance(record, dict):
        raise ValueError("record must be an object")
    if set(record.keys()) != {"id", "payload", "status"}:
        raise ValueError("record must have exactly id, payload, status")
    _validate_id(record["id"])
    status = record["status"]
    if not isinstance(status, str) or status not in _STATUSES:
        raise ValueError("invalid record status")
    _validate_payload(record["payload"])


class Inbox:
    def __init__(self, path):
        self.path = path
        self._records = self._load()
        if any(record["status"] == "running" for record in self._records):
            recovered = copy.deepcopy(self._records)
            for record in recovered:
                if record["status"] == "running":
                    record["status"] = "interrupted"
            self._save(recovered)
            self._records = recovered

    def _load(self):
        try:
            with open(self.path, "r", encoding="utf-8") as handle:
                text = handle.read()
        except FileNotFoundError:
            return []
        except OSError:
            raise
        try:
            document = json.loads(text)
        except ValueError as exc:
            raise ValueError("malformed inbox JSON: %s" % (exc,))
        return self._validate_document(document)

    @staticmethod
    def _validate_document(document):
        if not isinstance(document, dict):
            raise ValueError("document must be an object")
        if set(document.keys()) != {"version", "records"}:
            raise ValueError("document must have exactly version and records")
        version = document["version"]
        if isinstance(version, bool) or not isinstance(version, int) or version != _VERSION:
            raise ValueError("unsupported document version")
        records = document["records"]
        if not isinstance(records, list):
            raise ValueError("records must be a list")
        seen = set()
        for record in records:
            _validate_record(record)
            if record["id"] in seen:
                raise ValueError("duplicate record id")
            seen.add(record["id"])
        return [dict(record) for record in records]

    def _save(self, records):
        directory = os.path.dirname(os.path.abspath(self.path))
        os.makedirs(directory, exist_ok=True)
        prefix = os.path.basename(os.fspath(self.path)) + "."
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=prefix, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                json.dump(
                    {"version": _VERSION, "records": records},
                    handle,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    allow_nan=False,
                )
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp, self.path)
            tmp = None
        finally:
            if tmp is not None:
                try:
                    os.unlink(tmp)
                except OSError:
                    pass

    def snapshot(self):
        return copy.deepcopy(self._records)

    def submit(self, identifier, payload):
        _validate_id(identifier)
        _validate_payload(payload)
        stored = copy.deepcopy(payload)
        for record in self._records:
            if record["id"] == identifier:
                if _canonical(record["payload"]) == _canonical(stored):
                    return copy.deepcopy(record)
                raise ValueError("conflicting duplicate id: %s" % (identifier,))
        record = {"id": identifier, "payload": stored, "status": "pending"}
        candidate = copy.deepcopy(self._records)
        candidate.append(record)
        self._save(candidate)
        self._records = candidate
        return copy.deepcopy(record)

    def start_next(self):
        if any(record["status"] == "running" for record in self._records):
            raise RuntimeError("a record is already running")
        for index, record in enumerate(self._records):
            if record["status"] == "pending":
                candidate = copy.deepcopy(self._records)
                candidate[index]["status"] = "running"
                self._save(candidate)
                self._records = candidate
                return copy.deepcopy(candidate[index])
        return None

    def finish(self, identifier):
        for index, record in enumerate(self._records):
            if record["id"] != identifier:
                continue
            status = record["status"]
            if status == "completed":
                return copy.deepcopy(record)
            if status == "running":
                candidate = copy.deepcopy(self._records)
                candidate[index]["status"] = "completed"
                self._save(candidate)
                self._records = candidate
                return copy.deepcopy(candidate[index])
            raise ValueError("cannot finish record in status %s" % (status,))
        raise KeyError(identifier)

