"""Customer totals report.  Built on the shared pricing formula."""

from decimal import Decimal

import pricing

REPORT_FORMAT = 'customer-totals-v1'


def customer_totals(orders):
    """Return per-customer totals sorted by customer name.

    Every order is priced through ``pricing.price_line`` with the order's tier
    and the rounded line amounts are aggregated per customer.  An order without
    items still contributes a ``0.00`` row.  Caller data is never mutated.
    """
    totals = {}
    for order in orders or ():
        tier = order.get("tier", "bronze")
        subtotal = Decimal("0.00")
        for item in order.get("items") or ():
            subtotal += pricing.exact_amount(
                pricing.price_line(item["unit_price"], item["quantity"], tier)
            )
        customer = order["customer"]
        totals[customer] = totals.get(customer, Decimal("0.00")) + subtotal
    return [
        {"customer": customer, "total": pricing.format_amount(totals[customer])}
        for customer in sorted(totals)
    ]

