"""Deterministic route matching (no regex, no URL decoding).

Public API (unchanged):
    Router()                 -- create an empty route table
    Router.add(pattern, h)   -- register an opaque handler for a pattern
    Router.resolve(path)     -- -> (handler, params); never calls the handler
"""

import re

# A parameter segment is ":" followed by an ASCII identifier.
_PARAM_SEGMENT = re.compile(r":([A-Za-z_][A-Za-z0-9_]*)")


def _normalize(text):
    """Collapse repeated '/' and ignore trailing '/', yielding segments.

    The root string '/' (or any run of slashes) normalizes to the empty
    tuple, which is how the root route is represented.
    """
    return tuple(segment for segment in text.split('/') if segment)


def _validate_pattern(pattern):
    """Return the normalized segments of ``pattern`` or raise ValueError."""
    if not isinstance(pattern, str):
        raise ValueError('pattern must be a string starting with "/"')
    if not pattern.startswith('/'):
        raise ValueError('pattern must start with "/"')
    if '?' in pattern or '#' in pattern:
        raise ValueError('pattern may not contain "?" or "#"')

    segments = _normalize(pattern)
    seen = set()
    for segment in segments:
        if not segment.startswith(':'):
            # Every other character is literal.
            continue
        match = _PARAM_SEGMENT.fullmatch(segment)
        if match is None:
            raise ValueError('invalid parameter segment: %r' % (segment,))
        name = match.group(1)
        if name in seen:
            raise ValueError('duplicate parameter name: %r' % (name,))
        seen.add(name)
    return segments


def _validate_path(path):
    """Return the request segments of ``path`` or raise ValueError."""
    if not isinstance(path, str):
        raise ValueError('path must be a string starting with "/"')
    if not path.startswith('/'):
        raise ValueError('path must start with "/"')
    # Query string / fragment are ignored on resolve only.
    cut = len(path)
    for marker in '?#':
        index = path.find(marker)
        if index != -1 and index < cut:
            cut = index
    return _normalize(path[:cut])


class Router:
    def __init__(self):
        # List of (normalized segment tuple, handler) in registration order.
        self.routes = []

    def add(self, pattern, handler):
        """Register ``handler`` for ``pattern``.

        Re-adding the same normalized pattern replaces the handler but keeps
        the original registration order. An invalid pattern raises ValueError
        and leaves the route table untouched.
        """
        segments = _validate_pattern(pattern)
        for index, (existing, _handler) in enumerate(self.routes):
            if existing == segments:
                self.routes[index] = (segments, handler)
                return
        self.routes.append((segments, handler))

    def resolve(self, path):
        """Return ``(handler, params)`` for ``path`` or raise KeyError."""
        segments = _validate_path(path)

        best_handler = None
        best_params = None
        best_static = -1
        for pattern_segments, handler in self.routes:
            if len(pattern_segments) != len(segments):
                continue
            static = 0
            params = {}
            for wanted, actual in zip(pattern_segments, segments):
                if wanted.startswith(':'):
                    if not actual:  # a parameter captures a nonempty segment
                        break
                    params[wanted[1:]] = actual
                elif wanted == actual:
                    static += 1
                else:
                    break
            else:
                # Prefer the route with the most static segments; a strict
                # comparison keeps earlier registrations on ties.
                if static > best_static:
                    best_static = static
                    best_handler = handler
                    best_params = params

        if best_static < 0:
            raise KeyError(path)
        return best_handler, best_params

