files.inbox.py:
"""Recoverable, idempotent inbox persisted as a single JSON document.

Public contract (see README.md):

* ``Inbox(path)`` loads (and recovers) the inbox at *path*.
* ``submit(id, payload)`` registers a record idempotently.
* ``start_next()`` promotes the first pending record to ``running``.
* ``finish(id)`` completes a ``running`` record.
* ``snapshot()`` returns a detached deep copy of all records.

Every mutation is written durably (same-directory temporary file, flush,
``os.fsync``, ``os.replace``) *before* it is acknowledged.  On success the
in-memory state is swapped in; on failure the previous snapshot is left
exactly as it was.
"""

from __future__ import annotations

import copy
import json
import math
import os
import tempfile

__all__ = ["Inbox"]

VERSION = 1

PENDING = "pending"
RUNNING = "running"
COMPLETED = "completed"
INTERRUPTED = "interrupted"

STATUSES = frozenset({PENDING, RUNNING, COMPLETED, INTERRUPTED})

MAX_ID_LENGTH = 64

RECORD_FIELDS = frozenset({"id", "payload", "status"})
DOCUMENT_FIELDS = frozenset({"version", "records"})


# --------------------------------------------------------------------------
# validation helpers
# --------------------------------------------------------------------------

def validate_id(identifier):
    """Validate a record id and return it unchanged."""
    if not isinstance(identifier, str):
        raise ValueError("id must be a string")
    if not identifier:
        raise ValueError("id must not be empty")
    if len(identifier) > MAX_ID_LENGTH:
        raise ValueError("id must be at most %d characters" % MAX_ID_LENGTH)
    return identifier


def validate_payload(payload):
    """Validate a JSON value and return a detached deep copy of it."""
    if payload is None:
        return None
    if isinstance(payload, bool):
        return payload
    if isinstance(payload, str):
        return payload
    if isinstance(payload, int):
        return payload
    if isinstance(payload, float):
        if not math.isfinite(payload):
            raise ValueError("payload numbers must be finite")
        return payload
    if isinstance(payload, list):
        return [validate_payload(item) for item in payload]
    if isinstance(payload, dict):
        copied = {}
        for key, value in payload.items():
            if not isinstance(key, str):
                raise ValueError("payload object keys must be strings")
            copied[key] = validate_payload(value)
        return copied
    raise ValueError("payload must be a JSON value, got %r" % (type(payload).__name__,))


def canonical_payload(payload):
    """Canonical form used to decide whether two payloads are identical."""
    try:
        return json.dumps(
            payload,
            sort_keys=True,
            ensure_ascii=False,
            separators=(",", ":"),
            allow_nan=False,
        )
    except (TypeError, ValueError) as exc:
        raise ValueError("payload must be a JSON value") from exc
    except RecursionError as exc:  # pragma: no cover - defensive
        raise ValueError("payload is nested too deeply") from exc


def _reject_constant(name):
    raise ValueError("invalid JSON constant: %s" % (name,))


def _validate_record(record, seen_ids):
    if not isinstance(record, dict):
        raise ValueError("each record must be an object")
    if set(record) != RECORD_FIELDS:
        raise ValueError("record must have exactly id, payload and status")
    identifier = validate_id(record["id"])
    if identifier in seen_ids:
        raise ValueError("duplicate record id: %r" % (identifier,))
    seen_ids.add(identifier)
    status = record["status"]
    if status not in STATUSES:
        raise ValueError("invalid record status: %r" % (status,))
    payload = validate_payload(record["payload"])
    return {"id": identifier, "payload": payload, "status": status}


def validate_document(document):
    """Validate a loaded document and return detached records."""
    if not isinstance(document, dict):
        raise ValueError("document must be a JSON object")
    if set(document) != DOCUMENT_FIELDS:
        raise ValueError("document must have exactly version and records")
    version = document["version"]
    if isinstance(version, bool) or not isinstance(version, int) or version != VERSION:
        raise ValueError("unsupported document version: %r" % (version,))
    records = document["records"]
    if not isinstance(records, list):
        raise ValueError("records must be a list")
    seen_ids = set()
    return [_validate_record(record, seen_ids) for record in records]


# --------------------------------------------------------------------------
# the inbox
# --------------------------------------------------------------------------

class Inbox:
    """A single-process, single-writer, recoverable idempotent inbox."""

    def __init__(self, path):
        self.path = path
        self._records = []
        records = self._load()
        recovered = False
        for record in records:
            if record["status"] == RUNNING:
                # A record left running by a previous process can never be
                # finished by this one: recover it as interrupted.
                record["status"] = INTERRUPTED
                recovered = True
        if recovered:
            self._commit(records)
        else:
            self._records = records

    # -- public API --------------------------------------------------------

    def submit(self, identifier, payload):
        """Register *payload* under *identifier*, idempotently."""
        validate_id(identifier)
        payload_copy = validate_payload(payload)
        wanted = canonical_payload(payload_copy)
        for record in self._records:
            if record["id"] == identifier:
                if canonical_payload(record["payload"]) == wanted:
                    return copy.deepcopy(record)
                raise ValueError(
                    "conflicting payload for existing id: %r" % (identifier,)
                )
        records = copy.deepcopy(self._records)
        records.append({"id": identifier, "payload": payload_copy, "status": PENDING})
        self._commit(records)
        return copy.deepcopy(records[-1])

    def start_next(self):
        """Persist the first pending record as running and return it."""
        for record in self._records:
            if record["status"] == RUNNING:
                raise RuntimeError("a record is already running")
        for index, record in enumerate(self._records):
            if record["status"] == PENDING:
                records = copy.deepcopy(self._records)
                records[index]["status"] = RUNNING
                self._commit(records)
                return copy.deepcopy(records[index])
        return None

    def finish(self, identifier):
        """Persist a running record as completed and return it."""
        for index, record in enumerate(self._records):
            if record["id"] == identifier:
                if record["status"] == COMPLETED:
                    return copy.deepcopy(record)
                if record["status"] != RUNNING:
                    raise ValueError(
                        "cannot finish a %s record" % (record["status"],)
                    )
                records = copy.deepcopy(self._records)
                records[index]["status"] = COMPLETED
                self._commit(records)
                return copy.deepcopy(records[index])
        raise KeyError(identifier)

    def snapshot(self):
        """Return a detached deep copy of the records, in submission order."""
        return copy.deepcopy(self._records)

    # -- persistence -------------------------------------------------------

    def _load(self):
        target = os.path.abspath(os.fspath(self.path))
        try:
            with open(target, "r", encoding="utf-8") as handle:
                text = handle.read()
        except FileNotFoundError:
            return []
        try:
            document = json.loads(text, parse_constant=_reject_constant)
        except json.JSONDecodeError as exc:
            raise ValueError("inbox file is not valid JSON") from exc
        return validate_document(document)

    def _save(self, records):
        target = os.path.abspath(os.fspath(self.path))
        directory = os.path.dirname(target)
        os.makedirs(directory, exist_ok=True)
        data = json.dumps(
            {"version": VERSION, "records": records},
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8")
        descriptor, temporary = tempfile.mkstemp(
            prefix=os.path.basename(target) + ".", suffix=".tmp", dir=directory
        )
        try:
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, target)
        except BaseException:
            try:
                os.unlink(temporary)
            except OSError:
                pass
            raise

    def _commit(self, records):
        """Durably save *records*, then publish them as the new state."""
        self._save(records)
        self._records = records

