"""Normalize half-open interval coverage.

Public API:
    coverage(intervals, start, end) -> {'merged', 'gaps', 'covered'}

Intervals are half-open [lo, hi). They are clipped to the requested window
[start, end), empty clipped intervals are dropped, and the remainder is sorted
and merged (overlapping OR touching). Gaps are the sorted nonempty complement
of the merged intervals within the window.
"""


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _validate_bound(value, name):
    if not _is_int(value):
        raise ValueError(f"{name} must be an integer, not {type(value).__name__}")
    return value


def _validate_interval(item):
    if not isinstance(item, (list, tuple)):
        raise ValueError("each interval must be a list or tuple")
    if len(item) != 2:
        raise ValueError("each interval must have exactly two endpoints")
    lo, hi = item
    if not _is_int(lo) or not _is_int(hi):
        raise ValueError("interval endpoints must be integers")
    if lo > hi:
        raise ValueError("interval endpoints must satisfy lo <= hi")
    return lo, hi


def coverage(intervals, start, end):
    start = _validate_bound(start, "start")
    end = _validate_bound(end, "end")
    if start > end:
        raise ValueError("start must be <= end")

    try:
        items = list(intervals)
    except TypeError:
        raise ValueError("intervals must be a finite iterable")

    # Validate every interval up front, including ones wholly outside the
    # window, before clipping/ignoring anything.
    validated = [_validate_interval(item) for item in items]

    clipped = []
    for lo, hi in validated:
        lo = max(lo, start)
        hi = min(hi, end)
        if lo < hi:
            clipped.append((lo, hi))

    clipped.sort()

    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    gaps = []
    cursor = start
    for lo, hi in merged:
        if lo > cursor:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = sum(hi - lo for lo, hi in merged)

    return {"merged": merged, "gaps": gaps, "covered": covered}

