import unittest

from coverage import coverage


class TestCoverage(unittest.TestCase):
    def test_public_example(self):
        self.assertEqual(
            coverage([[3, 5], [-2, 2], [2, 4]], 0, 7),
            {"merged": [[0, 5]], "gaps": [[5, 7]], "covered": 5},
        )

    def test_empty_window(self):
        self.assertEqual(coverage([[1, 2]], 5, 5), {"merged": [], "gaps": [], "covered": 0})

    def test_no_intervals(self):
        self.assertEqual(coverage([], 1, 4), {"merged": [], "gaps": [[1, 4]], "covered": 0})

    def test_ignore_empty_and_outside(self):
        self.assertEqual(
            coverage([[0, 0], [10, 10], [-5, -1], [7, 9], [50, 60]], 0, 10),
            {"merged": [[7, 9]], "gaps": [[0, 7], [9, 10]], "covered": 2},
        )

    def test_touching_merges(self):
        self.assertEqual(
            coverage([[0, 2], [2, 4]], 0, 10),
            {"merged": [[0, 4]], "gaps": [[4, 10]], "covered": 4},
        )

    def test_nested_and_duplicates(self):
        self.assertEqual(
            coverage([[1, 9], [2, 3], [2, 3]], 0, 10),
            {"merged": [[1, 9]], "gaps": [[0, 1], [9, 10]], "covered": 8},
        )

    def test_clipping(self):
        self.assertEqual(
            coverage([[-100, 3], [8, 100]], 0, 10),
            {"merged": [[0, 3], [8, 10]], "gaps": [[3, 8]], "covered": 5},
        )

    def test_negative_and_huge(self):
        big = 10 ** 30
        self.assertEqual(
            coverage([[-big, big]], -big, big),
            {"merged": [[-big, big]], "gaps": [], "covered": 2 * big},
        )

    def test_adjacent_after_clip(self):
        self.assertEqual(
            coverage([[-5, 0], [0, 5]], 0, 5),
            {"merged": [[0, 5]], "gaps": [], "covered": 5},
        )

    def test_input_is_list_not_mutated_or_reordered(self):
        data = [[5, 6], [1, 2], [2, 3]]
        snapshot = [list(x) for x in data]
        coverage(data, 0, 10)
        self.assertEqual(data, snapshot)

    def test_tuple_intervals(self):
        self.assertEqual(
            coverage([(1, 2), (3, 4)], 0, 10),
            {"merged": [[1, 2], [3, 4]], "gaps": [[0, 1], [2, 3], [4, 10]], "covered": 2},
        )

    def test_generator(self):
        gen = (x for x in [[1, 3], [5, 6]])
        self.assertEqual(
            coverage(gen, 0, 10),
            {"merged": [[1, 3], [5, 6]], "gaps": [[0, 1], [3, 5], [6, 10]], "covered": 3},
        )

    def test_invalid_bound_types(self):
        for bad in (1.0, "1", True, None):
            with self.assertRaises(ValueError):
                coverage([], bad, 5)
            with self.assertRaises(ValueError):
                coverage([], 0, bad)

    def test_invalid_interval_shapes(self):
        for bad in ([[1]], [[1, 2, 3]], [(1,)], [1], ["ab"], [None, 1], [[1, 2.0]], [[True, 2]]):
            with self.assertRaises(ValueError):
                coverage(bad, 0, 10)

    def test_invalid_lo_gt_hi(self):
        with self.assertRaises(ValueError):
            coverage([[5, 1]], 0, 10)

    def test_invalid_interval_wholly_outside_window(self):
        with self.assertRaises(ValueError):
            coverage([[9, 3]], 100, 200)

    def test_interval_wholly_outside_valid_is_ignored(self):
        self.assertEqual(
            coverage([[100, 200], [-10, -5]], 0, 10),
            {"merged": [], "gaps": [[0, 10]], "covered": 0},
        )

    def test_bad_interval_type(self):
        with self.assertRaises(ValueError):
            coverage("abc", 0, 10)

    def test_start_gt_end(self):
        with self.assertRaises(ValueError):
            coverage([], 5, 4)


if __name__ == "__main__":
    unittest.main()

