import re

_PARAM_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")


def _collapse(path):
    segments = [segment for segment in path.split("/") if segment != ""]
    if not segments:
        return "/"
    return "/" + "/".join(segments)


def _to_segments(normalized):
    if normalized == "/":
        return []
    return normalized[1:].split("/")


def _strip_query(path):
    end = len(path)
    for marker in ("?", "#"):
        index = path.find(marker)
        if index != -1 and index < end:
            end = index
    return path[:end]


class Router:
    def __init__(self):
        self.routes = []

    def add(self, pattern, handler):
        if not isinstance(pattern, str):
            raise ValueError("pattern must be a string")
        if not pattern.startswith("/"):
            raise ValueError("pattern must start with '/'")
        if "?" in pattern or "#" in pattern:
            raise ValueError("pattern may not contain '?' or '#'")

        normalized = _collapse(pattern)
        compiled = []
        names = set()
        static_count = 0
        for segment in _to_segments(normalized):
            if segment.startswith(":"):
                name = segment[1:]
                if not _PARAM_NAME.match(name):
                    raise ValueError("invalid parameter name: %r" % (segment,))
                if name in names:
                    raise ValueError("duplicate parameter name: %r" % (name,))
                names.add(name)
                compiled.append(("param", name))
            else:
                compiled.append(("static", segment))
                static_count += 1

        entry = {
            "normalized": normalized,
            "segments": compiled,
            "static_count": static_count,
            "handler": handler,
        }
        for index, existing in enumerate(self.routes):
            if existing["normalized"] == normalized:
                self.routes[index] = entry
                return
        self.routes.append(entry)

    def resolve(self, path):
        if not isinstance(path, str):
            raise ValueError("path must be a string")
        if not path.startswith("/"):
            raise ValueError("path must start with '/'")

        path = _strip_query(path)
        parts = _to_segments(_collapse(path))

        best = None
        best_static = -1
        for route in self.routes:
            segments = route["segments"]
            if len(segments) != len(parts):
                continue
            params = {}
            matched = True
            for (kind, value), actual in zip(segments, parts):
                if kind == "static":
                    if value != actual:
                        matched = False
                        break
                else:
                    if actual == "":
                        matched = False
                        break
                    params[value] = actual
            if not matched:
                continue
            if route["static_count"] > best_static:
                best_static = route["static_count"]
                best = (route["handler"], params)

        if best is None:
            raise KeyError(path)
        return best

