"""Route matching for :class:`Router` (see README.md for the public contract).

The router keeps an ordered table of normalized patterns.  ``add`` validates a
pattern and stores it; ``resolve`` normalizes a path, finds every candidate with
the same number of segments and returns the one with the most static segments,
keeping registration order on ties.  Handlers are opaque values: they are never
called, copied or introspected.
"""

import re

_IDENTIFIER = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')
_QUERY_MARKERS = ('?', '#')


def _check_route_string(raw, kind):
    """Patterns and paths must be strs starting with '/'."""
    if not isinstance(raw, str):
        raise ValueError(
            "{0} must be a str starting with '/', got {1}".format(kind, type(raw).__name__)
        )
    if not raw.startswith('/'):
        raise ValueError("{0} must start with '/', got {1!r}".format(kind, raw))


def _split(raw):
    """Split a validated string; repeated '/' collapse and trailing '/' is ignored."""
    return tuple(segment for segment in raw.split('/') if segment)


def _parse_pattern(pattern):
    """Validate a pattern and return its normalized segments, else raise ValueError."""
    _check_route_string(pattern, 'pattern')
    for marker in _QUERY_MARKERS:
        if marker in pattern:
            raise ValueError("pattern may not contain {0!r}: {1!r}".format(marker, pattern))
    segments = _split(pattern)
    names = set()
    for segment in segments:
        if not segment.startswith(':'):
            continue  # static text: matched literally, never as a regex
        name = segment[1:]
        if _IDENTIFIER.fullmatch(name) is None:
            raise ValueError("invalid parameter segment {0!r} in {1!r}".format(segment, pattern))
        if name in names:
            raise ValueError("duplicate parameter name {0!r} in {1!r}".format(name, pattern))
        names.add(name)
    return segments


class Router:
    #: ordered ``(segments, handler)`` entries in registration order.
    routes = None

    def __init__(self):
        self.routes = []

    def add(self, pattern, handler):
        """Register ``handler`` for ``pattern``; re-adding replaces in place."""
        segments = _parse_pattern(pattern)  # fully validated before any mutation
        for index, (registered, _) in enumerate(self.routes):
            if registered == segments:
                self.routes[index] = (segments, handler)
                return
        self.routes.append((segments, handler))

    def resolve(self, path):
        """Return ``(handler, params)`` for ``path`` or raise KeyError."""
        _check_route_string(path, 'path')
        # On resolve only, the first '?' or '#' starts a query/fragment to drop.
        cut = len(path)
        for marker in _QUERY_MARKERS:
            index = path.find(marker)
            if index != -1 and index < cut:
                cut = index
        segments = _split(path[:cut])

        best_static = None
        best = None
        for pattern, handler in self.routes:  # registration order: ties keep it
            if len(pattern) != len(segments):
                continue
            params = {}
            static = 0
            for wanted, actual in zip(pattern, segments):
                if wanted.startswith(':'):
                    if not actual:  # a parameter captures one nonempty segment
                        break
                    params[wanted[1:]] = actual
                elif wanted == actual:
                    static += 1
                else:
                    break
            else:
                if best_static is None or static > best_static:
                    best_static = static
                    best = (handler, params)
        if best is None:
            raise KeyError(path)
        return best

