"""Command line interface: python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv."""

import csv
import io
import json
import os
import sys
import tempfile

from .model import summarize


def _read_records(path):
    records = []
    with open(path, "r", encoding="utf-8") as handle:
        for line in handle:
            if not line.strip():
                continue
            records.append(json.loads(line))
    return records


def _render_csv(summary):
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["customer", "count", "total"])
    for row in summary:
        writer.writerow([row["customer"], row["count"], row["total"]])
    return buffer.getvalue()


def _write_atomic(path, data):
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp = tempfile.mkstemp(dir=directory, prefix=".receipt_tmp_", suffix=".csv")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.write(data)
        os.replace(tmp, path)
    except BaseException:
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    if len(argv) != 2:
        print("usage: python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv", file=sys.stderr)
        return 2

    input_path, output_path = argv
    try:
        records = _read_records(input_path)
        summary = summarize(records)
        data = _render_csv(summary)
    except Exception as exc:
        print(str(exc) or "invalid input", file=sys.stderr)
        return 1

    try:
        _write_atomic(output_path, data)
    except OSError as exc:
        print(str(exc) or "unable to write output", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

