"""Core receipt summarization logic."""

import re
from decimal import Decimal, ROUND_HALF_UP

_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?\Z")
_CENT = Decimal("0.01")


def _validate(record):
    if not isinstance(record, dict):
        raise ValueError("receipt must be a mapping")
    if "customer" not in record:
        raise ValueError("missing customer")
    customer = record["customer"]
    if not isinstance(customer, str) or not customer.strip():
        raise ValueError("invalid customer")
    if "amount" not in record:
        raise ValueError("missing amount")
    amount = record["amount"]
    if not isinstance(amount, str) or _AMOUNT_RE.match(amount) is None:
        raise ValueError("invalid amount")
    if "status" not in record:
        raise ValueError("missing status")
    status = record["status"]
    if status != "paid" and status != "void":
        raise ValueError("invalid status")
    return customer.strip(), amount, status


def summarize(records):
    """Summarize receipt records.

    Returns a list of ``{"customer": str, "count": int, "total": str}`` dicts
    sorted by customer.  All records are validated, but only ``paid`` records
    contribute to the totals.
    """
    totals = {}
    counts = {}
    for record in records:
        name, amount, status = _validate(record)
        if status == "paid":
            totals[name] = totals.get(name, Decimal(0)) + Decimal(amount)
            counts[name] = counts.get(name, 0) + 1

    summary = []
    for name in sorted(totals):
        total = totals[name].quantize(_CENT, rounding=ROUND_HALF_UP)
        summary.append(
            {"customer": name, "count": counts[name], "total": str(total)}
        )
    return summary

