"""Normalize half-open interval coverage.

Public API:
    coverage(intervals, start, end) -> dict

See README.md for the full contract.
"""


def _is_int(value):
    """Return True for real Python integers, excluding bool."""
    return isinstance(value, int) and not isinstance(value, bool)


def _validate_bound(name, value):
    if not _is_int(value):
        raise ValueError(f"{name} must be an integer, got {value!r}")


def _validate_interval(item):
    """Validate one input item and return (lo, hi)."""
    if not isinstance(item, (list, tuple)):
        raise ValueError(
            f"each interval must be a two-element list or tuple, got {item!r}"
        )
    if len(item) != 2:
        raise ValueError(
            f"each interval must have exactly two elements, got {item!r}"
        )
    lo, hi = item
    if not _is_int(lo) or not _is_int(hi):
        raise ValueError(f"interval endpoints must be integers, got {item!r}")
    if lo > hi:
        raise ValueError(f"interval lower bound exceeds upper bound: {item!r}")
    return lo, hi


def coverage(intervals, start, end):
    """Clip, sort and merge half-open intervals within [start, end).

    Returns a dict with ``merged``, ``gaps`` and ``covered`` (integer length).
    """
    _validate_bound("start", start)
    _validate_bound("end", end)
    if start > end:
        raise ValueError(f"start ({start}) must be <= end ({end})")

    # Validate every interval, even those wholly outside the window, and
    # collect the non-empty clipped pieces.  Never mutate caller data.
    try:
        iterator = iter(intervals)
    except TypeError:
        raise ValueError(f"intervals must be iterable, got {intervals!r}")

    clipped = []
    for item in iterator:
        lo, hi = _validate_interval(item)
        clo = lo if lo > start else start
        chi = hi if hi < end else end
        if clo < chi:
            clipped.append([clo, chi])

    # Sort and merge overlapping or touching intervals.
    clipped.sort(key=lambda pair: pair[0])

    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    # Complement within [start, end) yields the sorted gaps.
    gaps = []
    cursor = start
    for lo, hi in merged:
        if lo > cursor:
            gaps.append([cursor, lo])
        if hi > cursor:
            cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = sum(hi - lo for lo, hi in merged)

    return {"merged": merged, "gaps": gaps, "covered": covered}

