"""Simple URL route matcher.

Public API (unchanged):
    Router.add(pattern, handler) -> None
    Router.resolve(path) -> (handler, params)

See README.md for the full contract.
"""

import re

# A whole parameter segment looks like ":name" with an ASCII identifier.
_PARAM_RE = re.compile(r"^:([A-Za-z_][A-Za-z0-9_]*)$")

# Sentinel used to distinguish "no match" from a matched handler of any value
# (including ``None``).
_MISSING = object()


def _require_path_like(value, kind):
    """Validate that *value* is a string starting with '/'."""
    if not isinstance(value, str):
        raise ValueError("%s must be a string, got %r" % (kind, type(value).__name__))
    if not value.startswith("/"):
        raise ValueError("%s must start with '/': %r" % (kind, value))


def _strip_query_and_fragment(path):
    """Return *path* truncated at the first '?' or '#' (if any)."""
    cut = len(path)
    for marker in ("?", "#"):
        pos = path.find(marker)
        if pos != -1 and pos < cut:
            cut = pos
    return path[:cut]


def _segments(value):
    """Normalize *value* into a tuple of non-empty segments.

    Collapses repeated '/' and ignores any leading/trailing '/'.  The root
    path '/' therefore becomes an empty tuple.
    """
    return tuple(seg for seg in value.split("/") if seg)


class Router:
    def __init__(self):
        # Each entry is (segments_tuple, handler).  Registration order is
        # preserved; adding a normalized duplicate replaces in place.
        self.routes = []

    def add(self, pattern, handler):
        _require_path_like(pattern, "pattern")
        if "?" in pattern or "#" in pattern:
            raise ValueError("pattern may not contain '?' or '#': %r" % pattern)

        segments = _segments(pattern)

        # Validate every segment *before* mutating self.routes so that an
        # invalid pattern never changes registered routes.
        seen = set()
        for segment in segments:
            if segment.startswith(":"):
                match = _PARAM_RE.match(segment)
                if match is None:
                    raise ValueError(
                        "invalid parameter segment: %r" % segment
                    )
                name = match.group(1)
                if name in seen:
                    raise ValueError("duplicate parameter name: %r" % name)
                seen.add(name)

        # All validated: replace an existing normalized pattern in place,
        # otherwise append.
        for index, (existing, _handler) in enumerate(self.routes):
            if existing == segments:
                self.routes[index] = (segments, handler)
                return
        self.routes.append((segments, handler))

    def resolve(self, path):
        _require_path_like(path, "path")
        path = _strip_query_and_fragment(path)
        # Truncation cannot remove the leading '/', but be safe nonetheless.
        _require_path_like(path, "path")

        parts = _segments(path)

        best_handler = _MISSING
        best_params = None
        best_static = -1

        for segments, handler in self.routes:
            if len(segments) != len(parts):
                continue

            params = {}
            static = 0
            for spec, actual in zip(segments, parts):
                if spec.startswith(":"):
                    # Normalization guarantees a non-empty segment.
                    params[spec[1:]] = actual
                elif spec == actual:
                    static += 1
                else:
                    break
            else:
                # More static segments win; strict '>' keeps the first
                # registered route on a tie.
                if static > best_static:
                    best_handler = handler
                    best_params = params
                    best_static = static

        if best_handler is _MISSING:
            raise KeyError(path)
        return best_handler, best_params

