"""Normalize half-open interval coverage.

Public API:
    coverage(intervals, start, end) -> {"merged": [...], "gaps": [...], "covered": int}

Intervals are treated as half-open ``[lo, hi)`` and clipped to the requested
window ``[start, end)``.  Only integer endpoints are accepted (``bool`` is not
an integer for this contract).  The implementation never enumerates individual
integers, so arbitrarily large Python integers are supported.
"""


def _as_int(value, label):
    """Return *value* as a plain int or raise ValueError."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{label} must be an integer, got {value!r}")
    return value


def coverage(intervals, start, end):
    """Compute merged coverage and gaps for *intervals* within [start, end)."""
    start = _as_int(start, "start")
    end = _as_int(end, "end")
    if start > end:
        raise ValueError("start must be less than or equal to end")

    # Materialize a finite iterable without touching the caller's object.
    try:
        items = list(intervals)
    except TypeError:
        raise ValueError("intervals must be a finite iterable") from None

    # Validate *every* item first, even those wholly outside the window, then
    # clip.  Clipped intervals that become empty are ignored.
    clipped = []
    for index, item in enumerate(items):
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError(
                f"interval at index {index} must be a two-element list or tuple"
            )
        lo = _as_int(item[0], f"interval[{index}][0]")
        hi = _as_int(item[1], f"interval[{index}][1]")
        if lo > hi:
            raise ValueError(
                f"interval at index {index} has lo > hi: [{lo}, {hi}]"
            )
        clo = lo if lo > start else start
        chi = hi if hi < end else end
        if clo < chi:
            clipped.append((clo, chi))

    # Sort a private list; merge overlapping or touching intervals.
    clipped.sort()
    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    # Gaps are the nonempty complement within the requested window.
    gaps = []
    cursor = start
    for lo, hi in merged:
        if lo > cursor:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = 0
    for lo, hi in merged:
        covered += hi - lo

    return {"merged": merged, "gaps": gaps, "covered": covered}

