"""Command line interface: ``python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv``."""

from __future__ import annotations

import csv
import json
import os
import sys
import tempfile
from typing import Iterable, List

from .model import summarize

USAGE = "usage: python -m receipt_tools.cli INPUT.jsonl OUTPUT.csv"


def _read_records(path: str) -> Iterable[dict]:
    with open(path, "r", encoding="utf-8") as handle:
        for line in handle:
            if not line.strip():
                continue
            yield json.loads(line)


def _write_csv(path: str, rows: List[dict]) -> None:
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(
        dir=directory, prefix=".receipt_tools_", suffix=".tmp"
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            writer = csv.writer(handle, lineterminator="\n")
            writer.writerow(["customer", "count", "total"])
            for row in rows:
                writer.writerow([row["customer"], row["count"], row["total"]])
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def main(argv: List[str] | None = None) -> int:
    if argv is None:
        argv = sys.argv[1:]

    if len(argv) != 2:
        print(USAGE, file=sys.stderr)
        return 2

    input_path, output_path = argv

    try:
        rows = summarize(_read_records(input_path))
    except (OSError, ValueError, UnicodeDecodeError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    try:
        _write_csv(output_path, rows)
    except OSError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    return 0


if __name__ == "__main__":
    sys.exit(main())

