"""Core summarization logic for receipt records."""

from __future__ import annotations

import re
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation
from typing import Any, Dict, Iterable, List

_AMOUNT_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?")

_CENT = Decimal("0.01")

_VALID_STATUSES = ("paid", "void")

_MISSING = object()


def _validated_amount(value: Any) -> str:
    if not isinstance(value, str) or _AMOUNT_RE.fullmatch(value) is None:
        raise ValueError(f"invalid amount: {value!r}")
    return value


def _validated_status(value: Any) -> str:
    if not isinstance(value, str) or value not in _VALID_STATUSES:
        raise ValueError(f"invalid status: {value!r}")
    return value


def summarize(records: Iterable[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Summarize an iterable of receipt dictionaries.

    Returns a list of ``{"customer": str, "count": int, "total": str}``
    dictionaries sorted by customer name.  Only ``paid`` rows contribute to a
    customer's total; every row is validated regardless of status.
    """

    totals: Dict[str, Decimal] = {}
    counts: Dict[str, int] = {}

    for record in records:
        if not isinstance(record, dict):
            raise ValueError(f"receipt must be a mapping, got {type(record).__name__}")

        customer = record.get("customer", _MISSING)
        if not isinstance(customer, str):
            raise ValueError(f"invalid customer: {customer!r}")
        name = customer.strip()
        if not name:
            raise ValueError("invalid customer: empty name")

        amount = _validated_amount(record.get("amount", _MISSING))
        status = _validated_status(record.get("status", _MISSING))

        if status != "paid":
            continue

        try:
            value = Decimal(amount)
        except InvalidOperation as exc:  # pragma: no cover - guarded by regex
            raise ValueError(f"invalid amount: {amount!r}") from exc

        totals[name] = totals.get(name, Decimal(0)) + value
        counts[name] = counts.get(name, 0) + 1

    summary: List[Dict[str, Any]] = []
    for name in sorted(totals):
        rounded = totals[name].quantize(_CENT, rounding=ROUND_HALF_UP)
        summary.append(
            {"customer": name, "count": counts[name], "total": str(rounded)}
        )
    return summary

files.coverage.py:
"""Normalize half-open interval coverage inside a requested window.

The public API is ``coverage(intervals, start, end)`` returning a dict with
``merged``, ``gaps`` and ``covered`` as described in README.md.

All values are Python integers (``bool`` is rejected); the implementation is
purely arithmetic, so arbitrarily large integers are handled in O(n log n)
time without enumerating the covered integers.
"""

from __future__ import annotations

__all__ = ["coverage"]


def _as_int(value, label):
    """Return ``value`` as a plain ``int`` or raise ``ValueError``."""
    # bool is a subclass of int but is not a valid endpoint / bound.
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{label} must be an integer, got {value!r}")
    return int(value)


def _validated_pairs(intervals):
    """Yield ``(lo, hi)`` integer pairs, validating the whole input first.

    Validation happens before any clipping, so an invalid interval raises
    ``ValueError`` even when it lies wholly outside the requested window.
    """
    if isinstance(intervals, (str, bytes, bytearray)):
        raise ValueError(
            "intervals must be a finite iterable of [lo, hi] pairs, "
            f"got {type(intervals).__name__}"
        )
    try:
        iterator = iter(intervals)
    except TypeError:
        raise ValueError(
            "intervals must be a finite iterable of [lo, hi] pairs, "
            f"got {type(intervals).__name__}"
        ) from None

    index = 0
    for item in iterator:
        if not isinstance(item, (list, tuple)) or isinstance(item, (str, bytes)):
            raise ValueError(
                f"interval #{index} must be a two-element list or tuple, "
                f"got {item!r}"
            )
        if len(item) != 2:
            raise ValueError(
                f"interval #{index} must have exactly two endpoints, got {item!r}"
            )
        lo = _as_int(item[0], f"interval #{index} lower endpoint")
        hi = _as_int(item[1], f"interval #{index} upper endpoint")
        if lo > hi:
            raise ValueError(
                f"interval #{index} has lower endpoint greater than upper "
                f"endpoint: {item!r}"
            )
        yield lo, hi
        index += 1


def coverage(intervals, start, end):
    """Coverage of half-open ``[lo, hi)`` intervals clipped to ``[start, end)``.

    Returns ``{'merged': [[lo, hi], ...], 'gaps': [[lo, hi], ...],
    'covered': int}`` where ``merged`` is the sorted, merged (overlapping or
    touching) coverage and ``gaps`` is the sorted nonempty complement inside
    the window.  The caller's sequence and its elements are never mutated.
    """
    start = _as_int(start, "start")
    end = _as_int(end, "end")
    if start > end:
        raise ValueError(f"start must be <= end, got start={start!r}, end={end!r}")

    clipped = []
    for lo, hi in _validated_pairs(intervals):
        if lo < start:
            lo = start
        if hi > end:
            hi = end
        if lo < hi:  # drop empty clipped intervals
            clipped.append((lo, hi))

    clipped.sort()

    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:  # overlapping or touching
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    gaps = []
    cursor = start
    for lo, hi in merged:
        if lo > cursor:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = sum(hi - lo for lo, hi in merged)
    return {"merged": merged, "gaps": gaps, "covered": covered}

