"""Extra checks for the coverage() contract (brute force oracle + edges)."""

import random
import unittest

from coverage import coverage


def brute_force(intervals, start, end):
    """Set-based reference implementation, only valid for tiny windows."""
    covered_ints = set()
    for lo, hi in intervals:
        for value in range(max(lo, start), min(hi, end)):
            covered_ints.add(value)
    runs = []
    for value in sorted(covered_ints):
        if runs and runs[-1][1] == value:
            runs[-1][1] = value + 1
        else:
            runs.append([value, value + 1])
    gaps = []
    cursor = start
    for lo, hi in runs:
        if lo > cursor:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])
    return {"merged": runs, "gaps": gaps, "covered": len(covered_ints)}


class Basics(unittest.TestCase):
    def test_smoke(self):
        self.assertEqual(
            coverage([[3, 5], [-2, 2], [2, 4]], 0, 7),
            {"merged": [[0, 5]], "gaps": [[5, 7]], "covered": 5},
        )

