        result = coverage([[0, 1], [1, 2], [2, 3]], 0, 4)
        self.assertEqual(result, {"merged": [[0, 3]], "gaps": [[3, 4]], "covered": 3})

    def test_nested_and_unsorted(self):
        result = coverage([[5, 9], [6, 7], [0, 3], [3, 5]], 0, 10)
        self.assertEqual(result, {"merged": [[0, 9]], "gaps": [[9, 10]], "covered": 9})

