class RandomOracle(unittest.TestCase):
    def test_matches_brute_force(self):
        rng = random.Random(20260929)
        for _ in range(400):
            start = rng.randint(-6, 6)
            end = start + rng.randint(0, 8)
            intervals = []
            for _ in range(rng.randint(0, 5)):
                lo = rng.randint(-10, 10)
                hi = lo + rng.randint(0, 6)
                intervals.append([lo, hi] if rng.random() < 0.5 else (lo, hi))
            self.assertEqual(
                coverage(intervals, start, end),
                brute_force([(a, b) for a, b in intervals], start, end),
                msg=(intervals, start, end),
            )

    def test_invariants(self):
        rng = random.Random(7)
        for _ in range(300):
            start = rng.randint(-5, 5)
            end = start + rng.randint(0, 10)
            intervals = [
                [rng.randint(-8, 8), rng.randint(-8, 8)] for _ in range(rng.randint(0, 4))
            ]
            intervals = [[a, b] if a <= b else [b, a] for a, b in intervals]
            result = coverage(intervals, start, end)
            merged, gaps = result["merged"], result["gaps"]
            self.assertEqual(result["covered"], sum(hi - lo for lo, hi in merged))
            self.assertEqual(
                merged,
                [span for span in merged if start <= span[0] < span[1] <= end],
            )
            for left, right in zip(merged, merged[1:]):
                self.assertLess(left[1], right[0])  # strictly separated
            for left, right in zip(gaps, gaps[1:]):
                self.assertLess(left[1], right[0])
            for span in gaps:
                self.assertTrue(start <= span[0] < span[1] <= end)
            total = sum(hi - lo for lo, hi in merged) + sum(hi - lo for lo, hi in gaps)
            self.assertEqual(total, end - start)


if __name__ == "__main__":
