"""Route matching with parameters.

Public API:
    Router()                  -- create an empty router
    router.add(pattern, h)    -- register a handler for a route pattern
    router.resolve(path)      -- return (handler, params) for the best match

See README.md for the full contract.
"""

import re

# A parameter is a whole segment ':' + ASCII identifier.
_IDENTIFIER = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")


def _normalize(value):
    """Collapse repeated '/' and drop a trailing '/' (root stays '/').

    Raises ValueError if *value* is not a string starting with '/'.
    """
    if not isinstance(value, str) or not value.startswith("/"):
        raise ValueError("path/pattern must be a string starting with '/'")
    segments = [segment for segment in value.split("/") if segment]
    return "/" + "/".join(segments)


def _split_segments(normalized):
    """Split a normalized path/pattern into its non-empty segments."""
    if normalized == "/":
        return []
    return normalized[1:].split("/")


def _parse_pattern(pattern):
    """Validate and parse *pattern*.

    Returns (normalized, parsed) where parsed is a list of
    ``(is_parameter, value)`` pairs; for parameters *value* is the name,
    for static segments it is the literal text.
    """
    if not isinstance(pattern, str) or not pattern.startswith("/"):
        raise ValueError("pattern must be a string starting with '/'")
    if "?" in pattern or "#" in pattern:
        raise ValueError("pattern may not contain '?' or '#'")

    normalized = _normalize(pattern)
    parsed = []
    seen = set()
    for segment in _split_segments(normalized):
        if segment.startswith(":"):
            name = segment[1:]
            if _IDENTIFIER.match(name) is None:
                raise ValueError("invalid parameter %r" % (segment,))
            if name in seen:
                raise ValueError("duplicate parameter name %r" % (name,))
            seen.add(name)
            parsed.append((True, name))
        else:
            parsed.append((False, segment))
    return normalized, parsed


class Router:
    def __init__(self):
        # Each entry: [normalized_pattern, parsed_segments, static_count, handler]
        self.routes = []

    def add(self, pattern, handler):
        normalized, parsed = _parse_pattern(pattern)
        static_count = sum(1 for is_param, _ in parsed if not is_param)

        for entry in self.routes:
            if entry[0] == normalized:
                # Same normalized pattern: replace handler, keep order.
                entry[1] = parsed
                entry[2] = static_count
                entry[3] = handler
                return
        self.routes.append([normalized, parsed, static_count, handler])

    def resolve(self, path):
        if not isinstance(path, str) or not path.startswith("/"):
            raise ValueError("path must be a string starting with '/'")
        original = path

        # On resolve only: discard the first '?' or '#' and everything after.
        for index, char in enumerate(path):
            if char == "?" or char == "#":
                path = path[:index]
                break

        segments = _split_segments(_normalize(path))

        best_handler = None
        best_params = None
        best_static = -1

        for _normalized, parsed, static_count, handler in self.routes:
            if len(parsed) != len(segments):
                continue
            if static_count <= best_static:
                continue

            params = {}
            matched = True
            for (is_param, value), actual in zip(parsed, segments):
                if is_param:
                    params[value] = actual
                elif value != actual:
                    matched = False
                    break
            if not matched:
                continue

            best_handler = handler
            best_params = params
            best_static = static_count

        if best_handler is None:
            raise KeyError(original)
        return best_handler, best_params

