"""Customer-level reporting, built on the shared :mod:`pricing` implementation."""

from __future__ import annotations

import pricing

__all__ = ["customer_totals", "REPORT_FORMAT"]

REPORT_FORMAT = "customer-totals-v1"


def customer_totals(orders):
    """Aggregate rounded line amounts per customer, sorted by customer.

    Each order supplies ``customer``, ``tier`` and ``items``.  The rounded line
    amounts are the ones produced by :func:`pricing.price_line`, so reports and
    checkout always agree.  A customer with no line items still gets a
    ``0.00`` row.  Caller dictionaries and lists are never mutated.
    """
    totals = {}
    for order in orders:
        tier = order.get("tier", "bronze")
        subtotal = pricing.to_decimal(0)
        for item in order["items"]:
            subtotal += pricing.to_decimal(
                pricing.price_line(item["unit_price"], item["quantity"], tier)
            )
        customer = order["customer"]
        totals[customer] = totals.get(customer, pricing.to_decimal(0)) + subtotal
    return [
        {"customer": customer, "total": pricing.format_amount(amount)}
        for customer, amount in sorted(totals.items())
    ]

