import decimal
from decimal import Decimal

import pricing

REPORT_FORMAT = 'customer-totals-v1'

_CENT = Decimal('0.01')
_PRECISION = 80


def _format(amount):
    return format(amount.quantize(_CENT), '.2f')


def customer_totals(orders):
    totals = {}
    with decimal.localcontext() as ctx:
        ctx.prec = _PRECISION
        for order in orders:
            customer = order['customer']
            tier = order.get('tier', 'bronze')
            pricing.validate_tier(tier)
            total = totals.get(customer, Decimal('0.00'))
            for item in order['items']:
                total += pricing.price_line(item['unit_price'], item['quantity'], tier)
            totals[customer] = total
        return [
            {'customer': customer, 'total': _format(total)}
            for customer, total in sorted(totals.items())
        ]

