import copy
import unittest
from decimal import Decimal, ROUND_HALF_UP

import checkout
import pricing
import reporting


class PriceLineTests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(pricing.price_line('2.00', 3), Decimal('6.00'))
        self.assertIsInstance(pricing.price_line('2.00', 3), Decimal)

    def test_tier_factors(self):
        self.assertEqual(pricing.price_line('10.00', 1, 'bronze'), Decimal('10.00'))
        self.assertEqual(pricing.price_line('10.00', 1, 'silver'), Decimal('9.00'))
        self.assertEqual(pricing.price_line('10.00', 1, 'gold'), Decimal('8.00'))

    def test_bulk_discount(self):
        self.assertEqual(pricing.price_line('1.00', 9), Decimal('9.00'))
        self.assertEqual(pricing.price_line('1.00', 10), Decimal('9.50'))
        self.assertEqual(pricing.price_line('1.00', 1000), Decimal('950.00'))

    def test_round_half_up(self):
        self.assertEqual(pricing.price_line('0.005', 1), Decimal('0.01'))
        self.assertEqual(pricing.price_line('0.015', 1), Decimal('0.02'))
        self.assertEqual(pricing.price_line('0.025', 1), Decimal('0.03'))
        self.assertEqual(pricing.price_line('2.345', 10, 'silver'), Decimal('20.05'))

    def test_single_rounding(self):
        # 1.005 * 1000 = 1005 -> *0.95 = 954.75 exactly if rounding only once.
        self.assertEqual(pricing.price_line('1.005', 1000), Decimal('954.75'))

    def test_invalid_money(self):
        for bad in ['', '.', '.5', '5.', '1e3', '-1', '+1', ' 1', '1 ', '1,2',
                    'abc', '1.2.3', 1, 1.0, None, True]:
            with self.assertRaises(ValueError, msg=bad):
                pricing.price_line(bad, 1)

    def test_invalid_quantity(self):
        for bad in [True, False, -1, 1.0, '1', None, Decimal(1)]:
            with self.assertRaises(ValueError, msg=bad):
                pricing.price_line('1.00', bad)

    def test_invalid_tier(self):
        for bad in ['platinum', 'Bronze', '', None, 1]:
            with self.assertRaises(ValueError, msg=bad):
                pricing.price_line('1.00', 1, bad)

    def test_size_limits(self):
        self.assertEqual(
            pricing.price_line('999999999999.999999', 1000, 'gold'),
            Decimal('760000000000000.00'),
        )


class CheckoutTests(unittest.TestCase):
    def test_order_and_total(self):
        items = [
            {'sku': 'a', 'unit_price': '1.005', 'quantity': 1},
            {'sku': 'b', 'unit_price': '0.004', 'quantity': 1},
        ]
        result = checkout.quote(items)
        self.assertEqual(result['lines'], [
