                {'sku': 'a', 'unit_price': '1.00', 'quantity': 1}]},
            {'customer': 'Ada', 'tier': 'gold', 'items': [
                {'sku': 'b', 'unit_price': '10.00', 'quantity': 1}]},
            {'customer': 'Zoe', 'tier': 'bronze', 'items': [
