        self.assertEqual(reporting.REPORT_FORMAT, 'customer-totals-v1')


class DynamicDispatchTests(unittest.TestCase):
    def test_replacement_affects_both(self):
        original = pricing.price_line
        seen = []

        def fake(unit_price, quantity, tier='bronze'):
            seen.append((unit_price, quantity, tier))
            return Decimal('9.99')

        pricing.price_line = fake
        try:
            result = checkout.quote([{'sku': 'a', 'unit_price': '1.00', 'quantity': 1}])
            report = reporting.customer_totals([
                {'customer': 'A', 'tier': 'gold', 'items': [
                    {'sku': 'a', 'unit_price': '1.00', 'quantity': 1}]}])
        finally:
            pricing.price_line = original

        self.assertEqual(result['lines'], [{'sku': 'a', 'amount': '9.99'}])
        self.assertEqual(result['total'], '9.99')
        self.assertEqual(report, [{'customer': 'A', 'total': '9.99'}])
        self.assertEqual(len(seen), 2)
        self.assertEqual(seen[1][2], 'gold')


if __name__ == '__main__':
    unittest.main()

