"""Normalize half-open interval coverage inside a requested window.

Public API
----------
``coverage(intervals, start, end)`` returns exactly::

    {'merged': [[lo, hi], ...], 'gaps': [[lo, hi], ...], 'covered': int}

Semantics
---------
* Intervals and the window ``[start, end)`` are half-open.
* All endpoints are Python integers; ``bool`` is rejected even though it is an
  ``int`` subclass.
* Every input item must be a two element ``list`` or ``tuple`` ``[lo, hi]``
  with ``lo <= hi``; anything else raises ``ValueError``.  Validation is
  exhaustive: an invalid interval raises even when it lies wholly outside the
  requested window (and even when the window is empty).
* Valid intervals are clipped to ``[start, end)``; clipped intervals that end
  up empty are ignored.
* The clipped intervals are sorted and merged when they overlap *or touch*.
* ``covered`` is the number of integer points covered by the merged intervals;
  it is computed from endpoints only, so arbitrarily large ranges are fine.
"""

from __future__ import annotations

__all__ = ["coverage"]


def _require_int(value, what):
    """Return *value* if it is a real integer, otherwise raise ValueError."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{what} must be an integer, got {value!r}")
    return value


def _validate_window(start, end):
    start = _require_int(start, "start")
    end = _require_int(end, "end")
    if start > end:
        raise ValueError(f"start must be <= end, got start={start!r}, end={end!r}")
    return start, end


def _clipped_intervals(intervals, start, end):
    """Validate *intervals* fully, then clip each one to ``[start, end)``."""
    try:
        items = iter(intervals)
    except TypeError:
        raise ValueError(
            "intervals must be a finite iterable of [lo, hi] pairs, "
            f"got {intervals!r}"
        ) from None

    clipped = []
    for index, item in enumerate(items):
        if not isinstance(item, (list, tuple)):
            raise ValueError(
                f"intervals[{index}] must be a list or tuple, got {item!r}"
            )
        if len(item) != 2:
            raise ValueError(
                f"intervals[{index}] must have exactly 2 elements, got {item!r}"
            )
        lo = _require_int(item[0], f"intervals[{index}][0]")
        hi = _require_int(item[1], f"intervals[{index}][1]")
        if lo > hi:
            raise ValueError(
                f"intervals[{index}] must satisfy lo <= hi, got {item!r}"
            )
        lo = lo if lo > start else start
        hi = hi if hi < end else end
        if lo < hi:
            clipped.append((lo, hi))
    return clipped


def coverage(intervals, start, end):
    """Return the normalized coverage of *intervals* clipped to ``[start, end)``."""
    start, end = _validate_window(start, end)
    clipped = _clipped_intervals(intervals, start, end)
    clipped.sort()

    merged = []
    if clipped:
        cur_lo, cur_hi = clipped[0]
        for lo, hi in clipped[1:]:
            if lo <= cur_hi:  # overlapping or touching
                if hi > cur_hi:
                    cur_hi = hi
            else:
                merged.append([cur_lo, cur_hi])
                cur_lo, cur_hi = lo, hi
        merged.append([cur_lo, cur_hi])

    gaps = []
    cursor = start
    for lo, hi in merged:
        if cursor < lo:
            gaps.append([cursor, lo])
        cursor = hi
    if cursor < end:
        gaps.append([cursor, end])

    covered = sum(hi - lo for lo, hi in merged)
    return {"merged": merged, "gaps": gaps, "covered": covered}

